import{_ as r,p as a,q as n,s as t,R as d,t as s,Y as o,n as h}from"./framework-e1bed10d.js";const c="/my-blog/assets/031_01-9f8e2f8d.png",p={},i=t("h1",{id:"分布式事务与数据一致性",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#分布式事务与数据一致性","aria-hidden":"true"},"#"),d(" 分布式事务与数据一致性")],-1),g={href:"https://mp.weixin.qq.com/s?__biz=MzIzNzQ5NjU5NQ==&mid=2247484867&idx=1&sn=1a8b0fc7ccae1b20949473dd8e152dfd&chksm=e8c6f5bfdfb17ca99eddcd1623eb33ced742a8fa97e21de248ef68527ff1bc70c7de50846248",target:"_blank",rel:"noopener noreferrer"},l=o('<hr><p>六、分布式事务与数据一致性</p><p>第五节我们讲到：聚合内部强一致，聚合之间最终一致。这一节，就把“聚合之间怎么最终一致”这件事，用工程的手段彻底讲透。这是微服务化后信贷系统最棘手的难题，也是无数线上事故的源头。</p><h3 id="一-强一致vs-最终一致-先想清楚能不能-同一个事务" tabindex="-1"><a class="header-anchor" href="#一-强一致vs-最终一致-先想清楚能不能-同一个事务" aria-hidden="true">#</a> （一）强一致vs 最终一致：先想清楚能不能“同一个事务”</h3><p>先建立一个最重要的判断框架。在做任何跨服务的数据一致性方案之前，你首先要想清楚一个问题：这两份数据，能不能放在同一个事务里？</p><p><img src="'+c+'" alt="图片"></p><p><strong>图4-34 强一致与最终一致的适用场景对比</strong></p><p>能放同一个事务的（强一致）：借据+ 还款计划、额度占用 + 额度记录，这些“必须要么一起成功、要么一起失败”的强相关数据，就应该在同一个聚合、同一个事务、甚至同一个数据库里处理。这是最省心的方案。靠第五节的聚合划分，把“必须强一致”的牢牢锁进一个聚合，是避免无数麻烦的根本手段。</p><p>不能放同一个事务的（最终一致）：跨服务、跨数据库、甚至跨系统的数据（比如借据和征信上报、借据和短信通知），没法用数据库事务保证，只能靠最终一致，“现在可能不一致，但通过补偿、重试、对账，最终会一致”。最终一致不是“不管了”，而是“用一套机制保证它最终收敛到一致”。</p><p>我给你的第一原则就一句话：能用强一致解决的，不要引入分布式事务；非得上分布式事务的，优先选最终一致的方案。因为分布式事务（尤其是强一致的2PC、以及补偿型的 TCC）性能差、实现复杂、失败处理难，是下下策，能不用就不用。</p><h3 id="二-四大方案-tcc、saga、本地消息表、最大努力通知" tabindex="-1"><a class="header-anchor" href="#二-四大方案-tcc、saga、本地消息表、最大努力通知" aria-hidden="true">#</a> （二）四大方案：TCC、Saga、本地消息表、最大努力通知</h3><p>信贷系统里常用的分布式事务方案，我按“一致性强度”给你排一遍，并逐个说清楚“是什么、适合信贷哪里、代价是什么”。</p><p><strong>表4-7分布式事务方案对比</strong></p><table><thead><tr><th><strong>方案</strong></th><th><strong>一致性</strong></th><th><strong>复杂度</strong></th><th><strong>信贷典型场景</strong></th><th><strong>备注</strong></th></tr></thead><tbody><tr><td>TCC</td><td>较强</td><td>高</td><td>放款（资源预占）</td><td>资金关键链路用</td></tr><tr><td>Saga</td><td>较弱</td><td>中</td><td>贷前→放款长流程</td><td>需容忍中间态</td></tr><tr><td>本地消息表</td><td>较弱</td><td>低</td><td>放款后异步通知</td><td>最常用的最终一致</td></tr><tr><td>最大努力通知</td><td>最弱</td><td>低</td><td>外部对账通知</td><td>靠对账兜底</td></tr></tbody></table><h3 id="三-技术落点·放款链路的一致性方案对比与选型" tabindex="-1"><a class="header-anchor" href="#三-技术落点·放款链路的一致性方案对比与选型" aria-hidden="true">#</a> （三）技术落点·放款链路的一致性方案对比与选型</h3><p>最后，我用放款这条贯穿全书的链路，把一致性方案完整演示一遍，给你一个可以直接复用的选型模板。</p><p>回看第二节的放款链路：额度校验/占用 → 合同状态更新 → 借据记账 → 资金划付 → 异步通知（短信通知/征信上报/还款计划生成）。这条链路里，不同环节的一致性诉求不同，选型也不同：</p><p><strong>表4-8放款链路一致性方案选型</strong></p><table><thead><tr><th><strong>环节</strong></th><th><strong>一致性诉求</strong></th><th><strong>推荐方案</strong></th><th><strong>理由</strong></th></tr></thead><tbody><tr><td>额度占用+借据记账</td><td>需较强保障，资金关键</td><td>TCC或 本地消息表</td><td>占用与记账是资金核心，要防重防漏</td></tr><tr><td>合同状态更新</td><td>与借据强相关</td><td>与借据同聚合/同事务</td><td>合同与借据强一致（聚合设计）</td></tr><tr><td>资金划付（对接支付）</td><td>跨系统</td><td>本地消息表+幂等</td><td>靠支付流水号幂等，异步划付</td></tr><tr><td>短信通知/征信上报/还款计划生成</td><td>弱一致</td><td>本地消息表/最大努力</td><td>可异步、可重试、靠对账兜底</td></tr></tbody></table><p>选型背后的三条决策逻辑，我帮你提炼出来（这套逻辑适用于信贷任何链路）：1.看是否涉资：涉及资金、涉及额度、涉及账务的环节（放款、扣款、记账），用较强的方案（TCC/本地消息表 + 强幂等）。2.看是否跨系统：跨支付、跨征信、跨外部系统，用本地消息表/最大努力通知 + 对账兜底，绝不指望强一致。 3. 看能否容忍中间态：能容忍中间态的长流程（签约→抵押→放款），用 Saga；不能容忍的，用 TCC。</p><p>我特别强调一个组合拳：分布式事务方案（TCC/消息表）+ 幂等 + 对账，三者缺一不可。分布式事务保证“不遗漏”、幂等保证“不重复”、对账保证“最终发现并纠正不一致”。只上分布式事务不上幂等，会重复；只上幂等不上对账，不一致发现不了。 这三件套一起上，信贷的资金链路才真正稳了。</p><h4 id="【监管红线提示·账实一致】" tabindex="-1"><a class="header-anchor" href="#【监管红线提示·账实一致】" aria-hidden="true">#</a> 【监管红线提示·账实一致】</h4><p>做分布式事务，我必须给你提监管红线：账实必须一致是监管的铁律。放款了账上必须有、扣款了余额必须对得上、还款了计划必须同步。任何“资金不一致”都可能被认定为重大风险事件。所以信贷的一致性方案，不只是技术选型，更是合规要求。你的系统里，涉及资金的所有环节，都必须有“幂等 + 对账”兜底，绝不能出现“账说不清”的模糊地带。</p>',23);function _(f,b){const e=h("ExternalLinkIcon");return a(),n("div",null,[i,t("blockquote",null,[t("p",null,[d("公众号：侃西东　·　发布日期：2026-10-17　·　"),t("a",g,[d("微信原文"),s(e)])])]),l])}const m=r(p,[["render",_],["__file","031.html.vue"]]);export{m as default};
